-- Contains: 20260101002400_results_guard.sql, 20260101002500_question_bank.sql, 20260101002600_exam_logistics.sql, 20260101002700_moderation.sql, 20260101002800_report_cards_plus.sql, 20260101002900_admissions_crm.sql, 20260101003000_review_fixes.sql, 20260101003100_community_crm.sql, 20260101003200_core_security.sql, 20260101003300_sis.sql, 20260101003400_lms_teaching.sql
