-- ---------- change history ----------
create table if not exists public.data_changes (
  id          bigint generated always as identity primary key,
  tenant_id   uuid not null,
  table_name  text not null,
  row_id      text,
  op          text not null check (op in ('insert','update','delete')),
  actor_id    uuid,
  actor       text not null default 'system',     -- user, guardian:<id>, public, system
  changes     jsonb not null default '{}'::jsonb,
  at          timestamptz not null default now()
);
create index if not exists data_changes_tenant_at on public.data_changes(tenant_id, at desc);
create index if not exists data_changes_row on public.data_changes(tenant_id, table_name, row_id);
create index if not exists data_changes_actor on public.data_changes(tenant_id, actor_id, at desc);
alter table public.data_changes enable row level security;
drop policy if exists data_changes_admin on public.data_changes;
create policy data_changes_admin on public.data_changes for select using (tenant_id = public.my_tenant_id() and public.is_school_admin());
revoke insert, update, delete on public.data_changes from anon, authenticated;

create or replace function public.log_data_change()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  o jsonb := case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end;
  n jsonb := case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end;
  src jsonb := coalesce(n, o);
  tid uuid := nullif(src ->> 'tenant_id', '')::uuid;
  diff jsonb := '{}'::jsonb;
  k text;
  claims jsonb := coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb;
  hdr jsonb := coalesce(nullif(current_setting('request.headers', true), ''), '{}')::jsonb;
  who uuid := auth.uid();
  label text := 'user';
  secret text[] := array['token','portal_token','pay_token','access_token','unsubscribe_token','update_token','card_code','code_hash',
    'secret','lead_webhook_key','offer_signature','p256dh','auth','endpoint','device_hash','referral_code'];
  noise text[] := array['updated_at','last_seen_at','last_message_at','staff_unread','guardian_unread','last_contact_at'];
  v jsonb;
begin
  if tid is null or tid::text = coalesce(current_setting('app.purging_tenant', true), '') then return null; end if;
  if not exists (select 1 from public.tenants where id = tid) then return null; end if;   -- the school itself is being deleted
  if who is null then
    -- The server acts for a person: it says who in a header, trusted only from the service role.
    if claims ->> 'role' = 'service_role' and coalesce(hdr ->> 'x-actor', '') <> '' then
      label := left(hdr ->> 'x-actor', 80);
      if label ~ '^user:[0-9a-f-]{36}$' then who := substr(label, 6)::uuid; label := 'user'; end if;
    else
      label := 'system';
    end if;
  end if;
  if tg_op = 'UPDATE' then
    for k in select jsonb_object_keys(n) loop
      if k = any(noise) or (n -> k) is not distinct from (o -> k) then continue; end if;
      diff := diff || jsonb_build_object(k, jsonb_build_array(o -> k, n -> k));
    end loop;
    if diff = '{}'::jsonb then return null; end if;
  else
    diff := src;
  end if;
  for k in select jsonb_object_keys(diff) loop
    if k = any(secret) then diff := jsonb_set(diff, array[k], '"[hidden]"'::jsonb);
    else
      v := diff -> k;
      if length(v::text) > 600 then diff := jsonb_set(diff, array[k], to_jsonb(left(v::text, 600) || '…')); end if;
    end if;
  end loop;
  insert into public.data_changes (tenant_id, table_name, row_id, op, actor_id, actor, changes)
    values (tid, tg_table_name, src ->> 'id', lower(tg_op), who, label, diff);
  return null;
end $$;

-- Every table holding a school's data, except high-volume logs and machine state.
do $$
declare t text;
begin
  for t in
    select c.table_name from information_schema.columns c
    join information_schema.tables x on x.table_schema = c.table_schema and x.table_name = c.table_name
    where c.table_schema = 'public' and c.column_name = 'tenant_id' and x.table_type = 'BASE TABLE'
      and c.table_name not in ('data_changes','audit_logs','platform_audit_logs','message_outbox','exam_events','exam_attempts','practice_sessions',
        'browser_events','environment_events','screen_snapshots','student_presence','session_participants','raise_hands','rtc_rooms','rtc_peers','rtc_signals',
        'transport_live','push_subscriptions','doc_counters','lead_sequence_runs','access_grants','phone_login_codes','quiz_attempts','quiz_answers',
        'activity_responses','game_sessions','game_players','leaderboard_entries','conversation_messages','pickup_attempts','device_enrollments','devices',
        'teacher_commands','survey_invites','tenants')
  loop
    execute format('drop trigger if exists zz_log_data_change on public.%I', t);
    execute format('create trigger zz_log_data_change after insert or update or delete on public.%I for each row execute function public.log_data_change()', t);
  end loop;
end $$;

-- Deleting a school skips the change history and removes it with everything else.
create or replace function public.platform_delete_tenant(p_tenant uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  r record;
  v_users uuid[];
  v_pass int := 0;
  v_blocked text[];
begin
  if not exists (select 1 from public.tenants where id = p_tenant) then raise exception 'school not found'; end if;
  perform set_config('app.purging_tenant', p_tenant::text, true);
  select coalesce(array_agg(id), '{}') into v_users from public.users where tenant_id = p_tenant;
  loop
    v_pass := v_pass + 1;
    v_blocked := '{}';
    for r in
      select c.table_name
      from information_schema.columns c
      join information_schema.tables t on t.table_schema = c.table_schema and t.table_name = c.table_name
      where c.table_schema = 'public' and c.column_name = 'tenant_id' and t.table_type = 'BASE TABLE'
        and c.table_name not in ('tenants', 'platform_audit_logs')   -- the platform keeps its history
      order by c.table_name
    loop
      begin
        execute format('delete from public.%I where tenant_id = $1', r.table_name) using p_tenant;
      exception when foreign_key_violation then
        v_blocked := v_blocked || r.table_name::text;
      end;
    end loop;
    exit when cardinality(v_blocked) = 0 or v_pass >= 15;
  end loop;
  if cardinality(v_blocked) > 0 then
    raise exception 'could not remove data from: %', array_to_string(v_blocked, ', ');
  end if;
  delete from public.tenants where id = p_tenant;
  perform set_config('app.purging_tenant', '', true);
  return jsonb_build_object('users', to_jsonb(v_users), 'passes', v_pass);
end $$;
revoke all on function public.platform_delete_tenant(uuid) from public, anon, authenticated;
grant execute on function public.platform_delete_tenant(uuid) to service_role;

grant all on public.school_sections, public.staff_devices, public.access_grants, public.phone_login_codes, public.consent_purposes,
  public.consent_records, public.data_changes to service_role;

-- ===== 20260101003300_sis.sql =====
-- =========================================================================
-- EduClass Fusion: student information system (phase 5).
--  * students: admission and leaving details (date admitted, previous
--    school, date left, how and why, destination school).
--  * student_movements: the enrolment history: admitted, promoted,
--    repeated, moved class, transferred in or out, withdrawn, graduated,
--    suspended, reinstated.
--  * student_documents: birth certificates, reports, medical and other
--    papers, stored privately; some may be shared with the family.
--  * sen_profiles, ieps, iep_targets, iep_reviews: special educational
--    needs, access arrangements (extra exam time and so on) and individual
--    education plans with targets and reviews.
--  * student_achievements and portfolio_items: awards, positions and
--    pieces of work.
--  * certificates: numbered, signed certificates (awards, transfer
--    certificates, testimonials) with a public verification link.
-- Apply AFTER 20260101003200. Idempotent.
-- =========================================================================

alter table public.students add column if not exists admitted_on date;
alter table public.students add column if not exists previous_school text;
alter table public.students add column if not exists left_on date;
alter table public.students add column if not exists leaving_kind text;
alter table public.students add column if not exists leaving_reason text;
alter table public.students add column if not exists destination_school text;
update public.students set admitted_on = created_at::date where admitted_on is null;
alter table public.students drop constraint if exists students_leaving_kind_check;
alter table public.students add constraint students_leaving_kind_check check (leaving_kind is null or leaving_kind in ('transferred','withdrawn','graduated','expelled','deceased','other'));

-- Who coordinates special educational needs (SENCO): admins, counsellors and named coordinators.
create or replace function public.is_sen_staff()
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_role(array['school_admin','principal','platform_admin','counsellor']);
$$;
grant execute on function public.is_sen_staff() to authenticated;

-- ---------- enrolment history ----------
create table if not exists public.student_movements (
  id                  uuid primary key default gen_random_uuid(),
  tenant_id           uuid not null references public.tenants(id) on delete cascade,
  student_id          uuid not null references public.students(id) on delete cascade,
  kind                text not null check (kind in ('admitted','promoted','repeated','class_change','transferred_in','transferred_out','withdrawn','graduated','suspended','reinstated','expelled','other')),
  effective_on        date not null default current_date,
  from_class          text,
  to_class            text,
  session_name        text,
  school              text,                 -- previous school (transferred in) or destination (transferred out)
  reason              text,
  notes               text,
  recorded_by         uuid references public.users(id) on delete set null,
  created_at          timestamptz not null default now()
);
create index if not exists student_movements_student on public.student_movements(student_id, effective_on desc);
create index if not exists student_movements_kind on public.student_movements(tenant_id, kind, effective_on desc);

-- ---------- documents ----------
create table if not exists public.student_documents (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  student_id         uuid not null references public.students(id) on delete cascade,
  kind               text not null default 'other' check (kind in ('birth_certificate','passport_photo','previous_report','transfer_letter','medical','immunisation','id_document','court_order','sen_report','certificate','agreement','other')),
  name               text not null,
  path               text not null,
  size               int,
  content_type       text,
  notes              text,
  shared_with_family boolean not null default false,
  confidential       boolean not null default false,   -- court orders, SEN and medical reports: admins, counsellors and nurse only
  uploaded_by        uuid references public.users(id) on delete set null,
  created_at         timestamptz not null default now()
);
create index if not exists student_documents_student on public.student_documents(student_id, created_at desc);
insert into storage.buckets (id, name, public) values ('student-documents', 'student-documents', false) on conflict (id) do nothing;

-- ---------- SEN and IEPs ----------
create table if not exists public.sen_profiles (
  student_id          uuid primary key references public.students(id) on delete cascade,
  tenant_id           uuid not null references public.tenants(id) on delete cascade,
  status              text not null default 'monitoring' check (status in ('monitoring','sen_support','ehcp','closed')),
  areas               text[] not null default '{}',   -- cognition_learning, communication_interaction, semh, sensory_physical
  needs               text[] not null default '{}',   -- dyslexia, adhd, autism, hearing, visual …
  summary             text,
  strengths           text,
  strategies          text,                            -- what helps in class: shared with the child's teachers
  extra_time_pct      int not null default 0 check (extra_time_pct between 0 and 100),
  arrangements        text[] not null default '{}',   -- reader, scribe, rest_breaks, separate_room, enlarged_print, assistive_tech, prompter
  agencies            text,                            -- outside professionals involved
  coordinator_id      uuid references public.users(id) on delete set null,
  share_with_teachers boolean not null default true,
  updated_by          uuid references public.users(id) on delete set null,
  updated_at          timestamptz not null default now(),
  created_at          timestamptz not null default now()
);

create table if not exists public.ieps (
  id               uuid primary key default gen_random_uuid(),
  tenant_id        uuid not null references public.tenants(id) on delete cascade,
  student_id       uuid not null references public.students(id) on delete cascade,
  title            text not null default 'Individual education plan',
  starts_on        date not null default current_date,
  review_on        date,
  status           text not null default 'draft' check (status in ('draft','active','closed')),
  student_voice    text,                       -- what the child says helps
  parent_views     text,
  parent_agreed_at timestamptz,
  created_by       uuid references public.users(id) on delete set null,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create index if not exists ieps_student on public.ieps(student_id, starts_on desc);
create index if not exists ieps_review on public.ieps(tenant_id, review_on) where status = 'active';

create table if not exists public.iep_targets (
  id                uuid primary key default gen_random_uuid(),
  tenant_id         uuid not null references public.tenants(id) on delete cascade,
  iep_id            uuid not null references public.ieps(id) on delete cascade,
  area              text,
  target            text not null check (length(target) between 2 and 1000),
  strategies        text,
  success_criteria  text,
  owner_id          uuid references public.users(id) on delete set null,
  progress          text not null default 'not_started' check (progress in ('not_started','emerging','developing','secure','achieved')),
  notes             text,
  position          int not null default 0,
  updated_at        timestamptz not null default now()
);

create table if not exists public.iep_reviews (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  iep_id        uuid not null references public.ieps(id) on delete cascade,
  reviewed_on   date not null default current_date,
  summary       text not null,
  attendees     text,
  next_review   date,
  created_by    uuid references public.users(id) on delete set null,
  created_at    timestamptz not null default now()
);

-- ---------- achievements and portfolio ----------
create table if not exists public.student_achievements (
  id                 uuid primary key default gen_random_uuid(),
  tenant_id          uuid not null references public.tenants(id) on delete cascade,
  student_id         uuid not null references public.students(id) on delete cascade,
  kind               text not null default 'academic' check (kind in ('academic','sports','arts','leadership','service','competition','attendance','character','other')),
  title              text not null check (length(title) between 2 and 160),
  description        text,
  level              text not null default 'school' check (level in ('class','school','local','state','national','international')),
  award              text,                  -- e.g. 1st place, Gold, Head Girl
  achieved_on        date not null default current_date,
  shared_with_family boolean not null default true,
  recorded_by        uuid references public.users(id) on delete set null,
  created_at         timestamptz not null default now()
);
create index if not exists student_achievements_student on public.student_achievements(student_id, achieved_on desc);

create table if not exists public.portfolio_items (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  student_id   uuid not null references public.students(id) on delete cascade,
  title        text not null check (length(title) between 2 and 160),
  description  text,
  kind         text not null default 'work' check (kind in ('work','project','artwork','writing','photo','video','audio','other')),
  subject_id   uuid references public.subjects(id) on delete set null,
  path         text,                         -- file in student-documents storage
  content_type text,
  link_url     text,                         -- or a link (video, website)
  status       text not null default 'approved' check (status in ('submitted','approved','returned')),
  shared_with_family boolean not null default true,
  added_by     uuid references public.users(id) on delete set null,
  reviewed_by  uuid references public.users(id) on delete set null,
  feedback     text,
  created_at   timestamptz not null default now()
);
create index if not exists portfolio_items_student on public.portfolio_items(student_id, created_at desc);

-- ---------- certificates ----------
create table if not exists public.certificates (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  student_id      uuid not null references public.students(id) on delete cascade,
  kind            text not null check (kind in ('award','transfer','testimonial','completion','attendance','participation','custom')),
  serial_no       text not null,
  title           text not null,
  body            text not null default '',
  data            jsonb not null default '{}'::jsonb,   -- the facts printed (snapshotted when issued)
  achievement_id  uuid references public.student_achievements(id) on delete set null,
  issued_on       date not null default current_date,
  signer_name     text,
  signer_title    text,
  status          text not null default 'issued' check (status in ('issued','revoked')),
  revoked_reason  text,
  revoked_at      timestamptz,
  signature       text,
  verify_token    text not null default encode(gen_random_bytes(16), 'hex'),
  shared_with_family boolean not null default true,
  issued_by       uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  unique (tenant_id, serial_no),
  unique (verify_token)
);
create index if not exists certificates_student on public.certificates(student_id, issued_on desc);

-- ---------- RLS ----------
alter table public.student_movements enable row level security;
drop policy if exists student_movements_read on public.student_movements;
create policy student_movements_read on public.student_movements for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists student_movements_admin on public.student_movements;
create policy student_movements_admin on public.student_movements for all using (tenant_id = public.my_tenant_id() and public.is_school_admin())
  with check (tenant_id = public.my_tenant_id() and public.is_school_admin());

-- Documents: staff see ordinary ones; confidential ones only admins, counsellors and the nurse. Families via the server.
alter table public.student_documents enable row level security;
drop policy if exists student_documents_read on public.student_documents;
create policy student_documents_read on public.student_documents for select using (
  tenant_id = public.my_tenant_id() and public.is_staff()
  and (not confidential or public.has_role(array['school_admin','principal','platform_admin','counsellor','nurse'])));
drop policy if exists student_documents_write on public.student_documents;
create policy student_documents_write on public.student_documents for all using (
  tenant_id = public.my_tenant_id() and public.has_role(array['school_admin','principal','platform_admin','it_admin','counsellor','nurse']))
  with check (tenant_id = public.my_tenant_id() and public.has_role(array['school_admin','principal','platform_admin','it_admin','counsellor','nurse']));

-- SEN: the SEN team manages; the named coordinator too; the child's teachers read the profile when it is shared with them.
alter table public.sen_profiles enable row level security;
drop policy if exists sen_profiles_team on public.sen_profiles;
create policy sen_profiles_team on public.sen_profiles for all using (
  tenant_id = public.my_tenant_id() and (public.is_sen_staff() or coordinator_id = auth.uid()))
  with check (tenant_id = public.my_tenant_id() and (public.is_sen_staff() or coordinator_id = auth.uid()));
drop policy if exists sen_profiles_teachers on public.sen_profiles;
create policy sen_profiles_teachers on public.sen_profiles for select using (
  tenant_id = public.my_tenant_id() and share_with_teachers and public.teaches_student(student_id));

create or replace function public.can_manage_sen(p_student uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_sen_staff() or exists (select 1 from public.sen_profiles where student_id = p_student and coordinator_id = auth.uid());
$$;
create or replace function public.can_read_sen(p_student uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.can_manage_sen(p_student)
    or (public.teaches_student(p_student) and exists (select 1 from public.sen_profiles where student_id = p_student and share_with_teachers));
$$;
grant execute on function public.can_manage_sen(uuid), public.can_read_sen(uuid) to authenticated;

alter table public.ieps enable row level security;
drop policy if exists ieps_manage on public.ieps;
create policy ieps_manage on public.ieps for all using (tenant_id = public.my_tenant_id() and public.can_manage_sen(student_id))
  with check (tenant_id = public.my_tenant_id() and public.can_manage_sen(student_id));
drop policy if exists ieps_read on public.ieps;
create policy ieps_read on public.ieps for select using (tenant_id = public.my_tenant_id() and status <> 'draft' and public.can_read_sen(student_id));

do $$
declare t text;
begin
  foreach t in array array['iep_targets','iep_reviews'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('drop policy if exists %I on public.%I', t || '_manage', t);
    execute format('create policy %I on public.%I for all using (tenant_id = public.my_tenant_id() and exists (select 1 from public.ieps i where i.id = %I.iep_id and public.can_manage_sen(i.student_id))) with check (tenant_id = public.my_tenant_id() and exists (select 1 from public.ieps i where i.id = %I.iep_id and public.can_manage_sen(i.student_id)))', t || '_manage', t, t, t);
    execute format('drop policy if exists %I on public.%I', t || '_read', t);
    execute format('create policy %I on public.%I for select using (tenant_id = public.my_tenant_id() and exists (select 1 from public.ieps i where i.id = %I.iep_id and i.status <> %L and public.can_read_sen(i.student_id)))', t || '_read', t, t, 'draft');
  end loop;
end $$;
-- Teachers who own a target record progress on it.
drop policy if exists iep_targets_owner on public.iep_targets;
create policy iep_targets_owner on public.iep_targets for update using (tenant_id = public.my_tenant_id() and owner_id = auth.uid())
  with check (tenant_id = public.my_tenant_id() and owner_id = auth.uid());

-- Achievements: any staff member records; everyone on staff reads; families through the server.
alter table public.student_achievements enable row level security;
drop policy if exists student_achievements_read on public.student_achievements;
create policy student_achievements_read on public.student_achievements for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or (shared_with_family and (public.is_guardian_of(student_id) or public.is_student_self(student_id)))));
drop policy if exists student_achievements_write on public.student_achievements;
create policy student_achievements_write on public.student_achievements for insert with check (tenant_id = public.my_tenant_id() and public.is_staff() and recorded_by = auth.uid());
drop policy if exists student_achievements_edit on public.student_achievements;
create policy student_achievements_edit on public.student_achievements for update using (tenant_id = public.my_tenant_id() and (recorded_by = auth.uid() or public.is_school_admin()))
  with check (tenant_id = public.my_tenant_id());
drop policy if exists student_achievements_delete on public.student_achievements;
create policy student_achievements_delete on public.student_achievements for delete using (tenant_id = public.my_tenant_id() and (recorded_by = auth.uid() or public.is_school_admin()));

-- Portfolio: staff manage; students see and add their own work through the server (it waits for a teacher).
alter table public.portfolio_items enable row level security;
drop policy if exists portfolio_staff on public.portfolio_items;
create policy portfolio_staff on public.portfolio_items for all using (tenant_id = public.my_tenant_id() and public.is_staff())
  with check (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists portfolio_own on public.portfolio_items;
create policy portfolio_own on public.portfolio_items for select using (tenant_id = public.my_tenant_id()
  and (public.is_student_self(student_id) or (status = 'approved' and shared_with_family and public.is_guardian_of(student_id))));

-- Certificates are numbered and signed by the server; staff read them, admins revoke through the server.
alter table public.certificates enable row level security;
drop policy if exists certificates_read on public.certificates;
create policy certificates_read on public.certificates for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or (shared_with_family and status = 'issued' and (public.is_guardian_of(student_id) or public.is_student_self(student_id)))));

grant all on public.student_movements, public.student_documents, public.sen_profiles, public.ieps, public.iep_targets, public.iep_reviews,
  public.student_achievements, public.portfolio_items, public.certificates to service_role;

-- Every new student starts their history with "admitted", however they were created.
alter table public.students alter column admitted_on set default current_date;
create or replace function public.student_admitted()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.student_movements (tenant_id, student_id, kind, effective_on, to_class, school, recorded_by)
  values (new.tenant_id, new.id, 'admitted', coalesce(new.admitted_on, current_date),
          (select name from public.class_groups where id = new.class_group_id), new.previous_school, auth.uid());
  return new;
end $$;
drop trigger if exists students_admitted on public.students;
create trigger students_admitted after insert on public.students for each row execute function public.student_admitted();
-- Students who were here before the history began.
insert into public.student_movements (tenant_id, student_id, kind, effective_on, to_class, notes)
select s.tenant_id, s.id, 'admitted', coalesce(s.admitted_on, s.created_at::date), c.name, 'Recorded when the enrolment history began'
from public.students s left join public.class_groups c on c.id = s.class_group_id
where not exists (select 1 from public.student_movements m where m.student_id = s.id);

-- ===== 20260101003400_lms_teaching.sql =====
-- =========================================================================
-- EduClass Fusion: learning management, part 1 (phase 6a).
--  * homework: late penalties, resubmission, file uploads, differentiated
--    groups, curriculum objectives; earlier attempts kept; annotations and
--    voice/video feedback on submissions; originality checks.
--  * learning_groups: support / core / extension groups inside a class.
--  * forums, forum_threads, forum_posts, forum_reports: class and school
--    discussion, moderated by staff.
--  * badges, student_badges, learning_activity: badges, points and streaks.
--  * curriculum_objectives, schemes_of_work, scheme_weeks: schemes of work
--    mapped to curriculum objectives, with approval and coverage.
-- Apply AFTER 20260101003300. Idempotent.
-- =========================================================================

-- ---------- differentiation ----------
create table if not exists public.learning_groups (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  class_group_id  uuid not null references public.class_groups(id) on delete cascade,
  name            text not null check (length(name) between 1 and 60),
  kind            text not null default 'custom' check (kind in ('support','core','extension','custom')),
  created_by      uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  unique (class_group_id, name)
);
create table if not exists public.learning_group_members (
  group_id    uuid not null references public.learning_groups(id) on delete cascade,
  student_id  uuid not null references public.students(id) on delete cascade,
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  primary key (group_id, student_id)
);

-- ---------- homework ----------
alter table public.homework add column if not exists late_penalty_pct numeric not null default 0;          -- % of the mark lost per day late
alter table public.homework add column if not exists late_penalty_max numeric not null default 100;       -- never lose more than this
alter table public.homework add column if not exists allow_resubmit boolean not null default false;
alter table public.homework add column if not exists max_attempts int not null default 1;
alter table public.homework add column if not exists accept_files boolean not null default true;
alter table public.homework add column if not exists group_ids uuid[] not null default '{}';            -- empty = the whole class
alter table public.homework add column if not exists objective_ids uuid[] not null default '{}';
alter table public.homework add column if not exists check_originality boolean not null default true;
do $$ begin
  alter table public.homework drop constraint if exists homework_late_rules_check;
  alter table public.homework add constraint homework_late_rules_check check (late_penalty_pct between 0 and 100 and late_penalty_max between 0 and 100 and max_attempts between 1 and 10);
end $$;

alter table public.homework_submissions add column if not exists attempt int not null default 1;
alter table public.homework_submissions add column if not exists files jsonb not null default '[]'::jsonb;         -- [{ path, name, type, size }]
alter table public.homework_submissions add column if not exists raw_score numeric;                              -- before any late penalty
alter table public.homework_submissions add column if not exists penalty_pct numeric not null default 0;
alter table public.homework_submissions add column if not exists status text not null default 'submitted';
alter table public.homework_submissions add column if not exists returned_note text;
alter table public.homework_submissions add column if not exists feedback_media jsonb not null default '[]'::jsonb; -- [{ path, type, seconds, created_at }]
alter table public.homework_submissions add column if not exists originality jsonb;                                -- { similarity, matches, style, checked_at }
do $$ begin
  alter table public.homework_submissions drop constraint if exists homework_submissions_status_check;
  alter table public.homework_submissions add constraint homework_submissions_status_check check (status in ('submitted','returned','marked'));
end $$;

-- Earlier attempts, kept when a student resubmits.
create table if not exists public.homework_submission_versions (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  submission_id uuid not null references public.homework_submissions(id) on delete cascade,
  attempt       int not null,
  body          text,
  files         jsonb not null default '[]'::jsonb,
  submitted_at  timestamptz not null,
  late          boolean not null default false,
  score         numeric,
  feedback      text,
  created_at    timestamptz not null default now()
);

create table if not exists public.submission_annotations (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  submission_id  uuid not null references public.homework_submissions(id) on delete cascade,
  author_id      uuid references public.users(id) on delete set null,
  kind           text not null check (kind in ('text','pin')),
  start_offset   int,            -- text: character range in the answer
  end_offset     int,
  quote          text,
  file_index     int,            -- pin: which uploaded image, and where (percent of width / height)
  x              numeric check (x between 0 and 100),
  y              numeric check (y between 0 and 100),
  comment        text not null check (length(comment) between 1 and 2000),
  created_at     timestamptz not null default now()
);
create index if not exists submission_annotations_sub on public.submission_annotations(submission_id);
insert into storage.buckets (id, name, public) values ('homework', 'homework', false) on conflict (id) do nothing;

-- ---------- forums ----------
create table if not exists public.forums (
  id              uuid primary key default gen_random_uuid(),
  tenant_id       uuid not null references public.tenants(id) on delete cascade,
  kind            text not null default 'class' check (kind in ('class','school','staff')),
  class_group_id  uuid references public.class_groups(id) on delete cascade,
  subject_id      uuid references public.subjects(id) on delete set null,
  title           text not null check (length(title) between 2 and 120),
  description     text,
  locked          boolean not null default false,
  created_by      uuid references public.users(id) on delete set null,
  created_at      timestamptz not null default now(),
  check (kind <> 'class' or class_group_id is not null)
);
create table if not exists public.forum_threads (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  forum_id       uuid not null references public.forums(id) on delete cascade,
  author_id      uuid references public.users(id) on delete set null,
  title          text not null check (length(title) between 2 and 160),
  body           text not null check (length(body) between 1 and 20000),
  pinned         boolean not null default false,
  locked         boolean not null default false,
  hidden         boolean not null default false,
  post_count     int not null default 0,
  last_post_at   timestamptz not null default now(),
  created_at     timestamptz not null default now()
);
create index if not exists forum_threads_forum on public.forum_threads(forum_id, pinned desc, last_post_at desc);
create table if not exists public.forum_posts (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  thread_id      uuid not null references public.forum_threads(id) on delete cascade,
  author_id      uuid references public.users(id) on delete set null,
  body           text not null check (length(body) between 1 and 20000),
  hidden         boolean not null default false,
  hidden_by      uuid references public.users(id) on delete set null,
  hidden_reason  text,
  edited_at      timestamptz,
  created_at     timestamptz not null default now()
);
create index if not exists forum_posts_thread on public.forum_posts(thread_id, created_at);
create table if not exists public.forum_reports (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  post_id      uuid references public.forum_posts(id) on delete cascade,
  thread_id    uuid references public.forum_threads(id) on delete cascade,
  reporter_id  uuid references public.users(id) on delete set null,
  reason       text not null check (length(reason) between 2 and 500),
  resolved_at  timestamptz,
  resolved_by  uuid references public.users(id) on delete set null,
  created_at   timestamptz not null default now()
);

-- Who may read and write in a forum: staff everywhere except they do not need a class link;
-- students only in school forums and their own class's forums; nobody else.
create or replace function public.can_use_forum(p_forum uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.forums f
    where f.id = p_forum and f.tenant_id = public.my_tenant_id()
      and (
        (public.is_staff())
        or (f.kind = 'school' and public.has_role(array['student']))
        or (f.kind = 'class' and exists (select 1 from public.students s where s.user_id = auth.uid() and s.status = 'active' and s.class_group_id = f.class_group_id))
      )
      and (f.kind <> 'staff' or public.is_staff())
  );
$$;
grant execute on function public.can_use_forum(uuid) to authenticated;

-- Locked forums and threads take no new posts; counts and last activity follow the posts.
create or replace function public.forum_post_guard()
returns trigger language plpgsql security definer set search_path = public as $$
declare t public.forum_threads; f public.forums;
begin
  select * into t from public.forum_threads where id = new.thread_id;
  select * into f from public.forums where id = t.forum_id;
  if tg_op = 'INSERT' then
    if (t.locked or f.locked) and not public.is_staff() then raise exception 'this discussion is closed'; end if;
    update public.forum_threads set post_count = post_count + 1, last_post_at = now() where id = t.id;
  end if;
  return new;
end $$;
drop trigger if exists forum_posts_guard on public.forum_posts;
create trigger forum_posts_guard before insert on public.forum_posts for each row execute function public.forum_post_guard();

-- ---------- gamification ----------
create table if not exists public.badges (
  id           uuid primary key default gen_random_uuid(),
  tenant_id    uuid not null references public.tenants(id) on delete cascade,
  name         text not null check (length(name) between 2 and 60),
  description  text,
  emoji        text not null default '🏅',
  rule         jsonb,            -- automatic: { type: streak|points|homework|practice|forum, threshold }; null = given by staff
  active       boolean not null default true,
  created_at   timestamptz not null default now(),
  unique (tenant_id, name)
);
create table if not exists public.student_badges (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  badge_id    uuid not null references public.badges(id) on delete cascade,
  student_id  uuid not null references public.students(id) on delete cascade,
  awarded_by  uuid references public.users(id) on delete set null,
  reason      text,
  awarded_at  timestamptz not null default now(),
  unique (badge_id, student_id)
);
create table if not exists public.learning_activity (
  id          bigint generated always as identity primary key,
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  student_id  uuid not null references public.students(id) on delete cascade,
  kind        text not null check (kind in ('homework','practice','content','path_step','forum','lesson','exam','tutor')),
  points      int not null default 0 check (points between 0 and 1000),
  ref_id      uuid,
  on_date     date not null default current_date,
  created_at  timestamptz not null default now()
);
create index if not exists learning_activity_student on public.learning_activity(student_id, on_date desc);
create unique index if not exists learning_activity_once on public.learning_activity(student_id, kind, ref_id) where ref_id is not null;

-- ---------- schemes of work ----------
create table if not exists public.curriculum_objectives (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade,
  subject_id  uuid references public.subjects(id) on delete cascade,
  level       text,                 -- e.g. JSS 1, Year 7
  framework   text,                 -- curriculum stage key, e.g. ng_jss
  code        text,                 -- e.g. BSc.1.2
  strand      text,                 -- theme / topic area
  statement   text not null check (length(statement) between 3 and 1000),
  position    int not null default 0,
  created_at  timestamptz not null default now()
);
create index if not exists curriculum_objectives_subject on public.curriculum_objectives(tenant_id, subject_id, level);

create table if not exists public.schemes_of_work (
  id            uuid primary key default gen_random_uuid(),
  tenant_id     uuid not null references public.tenants(id) on delete cascade,
  subject_id    uuid not null references public.subjects(id) on delete cascade,
  level         text not null,
  term_id       uuid references public.terms(id) on delete set null,
  title         text not null check (length(title) between 2 and 160),
  owner_id      uuid not null references public.users(id),
  status        text not null default 'draft' check (status in ('draft','submitted','approved','returned')),
  review_note   text,
  reviewed_by   uuid references public.users(id) on delete set null,
  reviewed_at   timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create table if not exists public.scheme_weeks (
  id             uuid primary key default gen_random_uuid(),
  tenant_id      uuid not null references public.tenants(id) on delete cascade,
  scheme_id      uuid not null references public.schemes_of_work(id) on delete cascade,
  week_no        int not null check (week_no between 1 and 52),
  topic          text not null check (length(topic) between 1 and 200),
  objective_ids  uuid[] not null default '{}',
  activities     text,
  resources      text,
  assessment     text,
  status         text not null default 'planned' check (status in ('planned','taught','skipped')),
  taught_on      date,
  note           text,
  updated_at     timestamptz not null default now(),
  unique (scheme_id, week_no)
);
alter table public.lesson_notes add column if not exists scheme_week_id uuid references public.scheme_weeks(id) on delete set null;

-- Approving a scheme: admins, the principal, QA or the head of the subject's department; never the author.
create or replace function public.can_review_scheme(p_subject uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.has_role(array['school_admin','principal','qa_officer','platform_admin'])
    or exists (select 1 from public.subjects s join public.departments d on d.id = s.department_id where s.id = p_subject and d.head_user_id = auth.uid());
$$;
grant execute on function public.can_review_scheme(uuid) to authenticated;
create or replace function public.schemes_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then return new; end if;
  if new.status is distinct from old.status and new.status in ('approved','returned') then
    if not public.can_review_scheme(new.subject_id) then raise exception 'only the head of department, QA, the principal or admins can review a scheme of work'; end if;
    if old.owner_id = auth.uid() then raise exception 'you cannot approve your own scheme of work'; end if;
  end if;
  if new.owner_id is distinct from old.owner_id and not public.is_school_admin() then raise exception 'only admins can hand a scheme to someone else'; end if;
  return new;
end $$;
drop trigger if exists schemes_guard on public.schemes_of_work;
create trigger schemes_guard before update on public.schemes_of_work for each row execute function public.schemes_guard();

-- ---------- RLS ----------
alter table public.learning_groups enable row level security;
alter table public.learning_group_members enable row level security;
drop policy if exists learning_groups_staff on public.learning_groups;
create policy learning_groups_staff on public.learning_groups for all using (tenant_id = public.my_tenant_id() and public.is_staff())
  with check (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists learning_group_members_staff on public.learning_group_members;
create policy learning_group_members_staff on public.learning_group_members for all using (tenant_id = public.my_tenant_id() and public.is_staff())
  with check (tenant_id = public.my_tenant_id() and public.is_staff());

alter table public.homework_submission_versions enable row level security;
drop policy if exists hw_versions_read on public.homework_submission_versions;
create policy hw_versions_read on public.homework_submission_versions for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or exists (select 1 from public.homework_submissions s where s.id = submission_id and (public.is_student_self(s.student_id) or public.is_guardian_of(s.student_id)))));

alter table public.submission_annotations enable row level security;
drop policy if exists annotations_staff on public.submission_annotations;
create policy annotations_staff on public.submission_annotations for all using (tenant_id = public.my_tenant_id() and public.is_staff())
  with check (tenant_id = public.my_tenant_id() and public.is_staff() and author_id = auth.uid());
drop policy if exists annotations_family on public.submission_annotations;
create policy annotations_family on public.submission_annotations for select using (tenant_id = public.my_tenant_id()
  and exists (select 1 from public.homework_submissions s where s.id = submission_id and s.status <> 'submitted' and (public.is_student_self(s.student_id) or public.is_guardian_of(s.student_id))));

alter table public.forums enable row level security;
drop policy if exists forums_read on public.forums;
create policy forums_read on public.forums for select using (public.can_use_forum(id));
drop policy if exists forums_staff on public.forums;
create policy forums_staff on public.forums for all using (tenant_id = public.my_tenant_id() and public.is_staff())
  with check (tenant_id = public.my_tenant_id() and public.is_staff());

alter table public.forum_threads enable row level security;
drop policy if exists forum_threads_read on public.forum_threads;
create policy forum_threads_read on public.forum_threads for select using (public.can_use_forum(forum_id) and (not hidden or public.is_staff() or author_id = auth.uid()));
drop policy if exists forum_threads_insert on public.forum_threads;
create policy forum_threads_insert on public.forum_threads for insert with check (tenant_id = public.my_tenant_id() and author_id = auth.uid() and public.can_use_forum(forum_id)
  and not pinned and not locked and not hidden
  and (public.is_staff() or not exists (select 1 from public.forums f where f.id = forum_id and f.locked)));
drop policy if exists forum_threads_staff on public.forum_threads;
create policy forum_threads_staff on public.forum_threads for update using (tenant_id = public.my_tenant_id() and public.is_staff()) with check (tenant_id = public.my_tenant_id());
drop policy if exists forum_threads_delete on public.forum_threads;
create policy forum_threads_delete on public.forum_threads for delete using (tenant_id = public.my_tenant_id() and (public.is_staff() or (author_id = auth.uid() and post_count = 0)));

alter table public.forum_posts enable row level security;
drop policy if exists forum_posts_read on public.forum_posts;
create policy forum_posts_read on public.forum_posts for select using (tenant_id = public.my_tenant_id()
  and exists (select 1 from public.forum_threads t where t.id = thread_id and public.can_use_forum(t.forum_id))
  and (not hidden or public.is_staff() or author_id = auth.uid()));
drop policy if exists forum_posts_insert on public.forum_posts;
create policy forum_posts_insert on public.forum_posts for insert with check (tenant_id = public.my_tenant_id() and author_id = auth.uid() and not hidden
  and exists (select 1 from public.forum_threads t where t.id = thread_id and public.can_use_forum(t.forum_id) and not t.hidden));
-- Authors edit their own words; staff hide posts.
drop policy if exists forum_posts_update on public.forum_posts;
create policy forum_posts_update on public.forum_posts for update using (tenant_id = public.my_tenant_id() and (author_id = auth.uid() or public.is_staff()))
  with check (tenant_id = public.my_tenant_id());
create or replace function public.forum_post_edit_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null or public.is_staff() then return new; end if;
  if new.hidden is distinct from old.hidden or new.hidden_by is distinct from old.hidden_by or new.thread_id <> old.thread_id or new.author_id is distinct from old.author_id then
    raise exception 'only staff can moderate posts';
  end if;
  new.edited_at := now();
  return new;
end $$;
drop trigger if exists forum_posts_edit_guard on public.forum_posts;
create trigger forum_posts_edit_guard before update on public.forum_posts for each row execute function public.forum_post_edit_guard();
drop policy if exists forum_posts_delete on public.forum_posts;
create policy forum_posts_delete on public.forum_posts for delete using (tenant_id = public.my_tenant_id() and public.is_school_admin());

alter table public.forum_reports enable row level security;
drop policy if exists forum_reports_insert on public.forum_reports;
create policy forum_reports_insert on public.forum_reports for insert with check (tenant_id = public.my_tenant_id() and reporter_id = auth.uid());
drop policy if exists forum_reports_staff on public.forum_reports;
create policy forum_reports_staff on public.forum_reports for all using (tenant_id = public.my_tenant_id() and public.is_staff()) with check (tenant_id = public.my_tenant_id());

alter table public.badges enable row level security;
drop policy if exists badges_read on public.badges;
create policy badges_read on public.badges for select using (tenant_id = public.my_tenant_id());
drop policy if exists badges_staff on public.badges;
create policy badges_staff on public.badges for all using (tenant_id = public.my_tenant_id() and public.is_school_admin()) with check (tenant_id = public.my_tenant_id() and public.is_school_admin());
alter table public.student_badges enable row level security;
drop policy if exists student_badges_read on public.student_badges;
create policy student_badges_read on public.student_badges for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or public.is_student_self(student_id) or public.is_guardian_of(student_id)));
drop policy if exists student_badges_award on public.student_badges;
create policy student_badges_award on public.student_badges for insert with check (tenant_id = public.my_tenant_id() and public.is_staff() and awarded_by = auth.uid()
  and exists (select 1 from public.badges b where b.id = badge_id and b.rule is null));
drop policy if exists student_badges_remove on public.student_badges;
create policy student_badges_remove on public.student_badges for delete using (tenant_id = public.my_tenant_id() and (awarded_by = auth.uid() or public.is_school_admin()));
alter table public.learning_activity enable row level security;
drop policy if exists learning_activity_read on public.learning_activity;
create policy learning_activity_read on public.learning_activity for select using (tenant_id = public.my_tenant_id()
  and (public.is_staff() or public.is_student_self(student_id) or public.is_guardian_of(student_id)));

alter table public.curriculum_objectives enable row level security;
drop policy if exists objectives_read on public.curriculum_objectives;
create policy objectives_read on public.curriculum_objectives for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists objectives_write on public.curriculum_objectives;
create policy objectives_write on public.curriculum_objectives for all using (tenant_id = public.my_tenant_id() and (public.is_school_admin() or public.has_role(array['qa_officer','teacher'])))
  with check (tenant_id = public.my_tenant_id() and (public.is_school_admin() or public.has_role(array['qa_officer','teacher'])));

alter table public.schemes_of_work enable row level security;
drop policy if exists schemes_read on public.schemes_of_work;
create policy schemes_read on public.schemes_of_work for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists schemes_insert on public.schemes_of_work;
create policy schemes_insert on public.schemes_of_work for insert with check (tenant_id = public.my_tenant_id() and public.is_staff() and owner_id = auth.uid() and status in ('draft','submitted'));
drop policy if exists schemes_update on public.schemes_of_work;
create policy schemes_update on public.schemes_of_work for update using (tenant_id = public.my_tenant_id() and (owner_id = auth.uid() or public.can_review_scheme(subject_id)))
  with check (tenant_id = public.my_tenant_id());
drop policy if exists schemes_delete on public.schemes_of_work;
create policy schemes_delete on public.schemes_of_work for delete using (tenant_id = public.my_tenant_id() and ((owner_id = auth.uid() and status in ('draft','returned')) or public.is_school_admin()));

alter table public.scheme_weeks enable row level security;
drop policy if exists scheme_weeks_read on public.scheme_weeks;
create policy scheme_weeks_read on public.scheme_weeks for select using (tenant_id = public.my_tenant_id() and public.is_staff());
drop policy if exists scheme_weeks_write on public.scheme_weeks;
create policy scheme_weeks_write on public.scheme_weeks for all using (tenant_id = public.my_tenant_id()
  and exists (select 1 from public.schemes_of_work s where s.id = scheme_id and (s.owner_id = auth.uid() or public.can_review_scheme(s.subject_id))))
  with check (tenant_id = public.my_tenant_id()
  and exists (select 1 from public.schemes_of_work s where s.id = scheme_id and (s.owner_id = auth.uid() or public.can_review_scheme(s.subject_id))));

grant all on public.learning_groups, public.learning_group_members, public.homework_submission_versions, public.submission_annotations, public.forums,
  public.forum_threads, public.forum_posts, public.forum_reports, public.badges, public.student_badges, public.learning_activity, public.curriculum_objectives,
  public.schemes_of_work, public.scheme_weeks to service_role;
